def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    own = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_def = sum(1 for x in opp if x == 'D')
    own_def = sum(1 for x in own if x == 'D')
    last_opp = opp[-1]
    last_own = own[-1]

    if opp_def == 0:
        if own_def == 0:
            if n < 3:
                return 'C'
            else:
                return 'D'
        else:
            return 'D'

    first_my_def = None
    for i, m in enumerate(own):
        if m == 'D':
            first_my_def = i
            break
    first_opp_def = None
    for i, o in enumerate(opp):
        if o == 'D':
            first_opp_def = i
            break

    opp_first = False
    if first_opp_def is not None:
        if first_my_def is None or first_opp_def < first_my_def:
            opp_first = True

    if opp_first:
        if opp_def > n // 2:
            return 'D'
        if last_opp == 'D':
            if last_own == 'D':
                if rng.random() < 0.3:
                    return 'C'
                else:
                    return 'D'
            else:
                return 'D'
        else:
            if last_own == 'D':
                return 'D'
            else:
                return 'C'
    else:
        if last_opp == 'D':
            if last_own == 'D':
                return 'C'
            else:
                if n >= 2 and own[-2] == 'D':
                    return 'C'
                else:
                    return 'D'
        else:
            if last_own == 'D':
                return 'D'
            else:
                return 'C'
